"""Stage 98: the testing and verification chapter (docs/64, generated by tools/analyze_testing_docs.py) is current; every claim names register entries and chapters that exist; its counts are the real ones (the register, the test modules, the CMake tests,
the discrepancy ledger); the open items are exactly those the other chapters say."""
import glob
import os
import re
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_testing_docs as T  # noqa: E402

DOC = os.path.join(ROOT, "docs", "64-testing-and-verification.md")


class TestingDocs(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open(DOC, encoding="utf-8", newline="") as fh:
            cls.text = fh.read().replace("\r\n", "\n")
        cls.ov, cls.cs = T.register()

    def test_the_chapter_is_current(self):
        self.assertEqual(self.text, T.doc(), "regenerate: python -I tools/analyze_testing_docs.py --doc docs/64-testing-and-verification.md")

    def test_every_claim_names_register_entries_and_chapters_that_exist(self):
        ovs = {x[0] for x in self.ov}
        cs = {int(m.group(1)) for m in (re.match(r"\| C-(\d+) ", l) for l in self.cs) if m}
        for claim, how, result, reg, chapters in T.CLAIMS:
            for m in re.finditer(r"C-(\d+)(?: to C-(\d+))?", reg):
                lo = int(m.group(1))
                hi = int(m.group(2) or m.group(1))
                self.assertIn(lo, cs, reg)
                self.assertIn(hi, cs, reg)
            for m in re.finditer(r"OV-(\d+)", reg):
                self.assertIn("OV-" + m.group(1), ovs, reg)
            for n in re.findall(r"`(\d\d)`", chapters):
                self.assertTrue(glob.glob(os.path.join(ROOT, "docs", n + "-*.md")), "no chapter " + n)

    def test_the_counts_are_the_real_ones(self):
        per, other, nmods, ntests = T.test_inventory()
        self.assertEqual(nmods, len(glob.glob(os.path.join(ROOT, "tests", "test_*.py"))))
        self.assertEqual(sum(v[0] for v in per.values()) + other[0], nmods)
        self.assertEqual(sum(v[1] for v in per.values()) + other[1], ntests)
        self.assertIn("**%d test modules with %d test functions**" % (nmods, ntests), self.text)
        self.assertIn("**%d tests** under `ctest`" % len(T.cmake_tests()), self.text)
        self.assertIn("%d numbered results (C-nn)" % len(self.cs), self.text)

    def test_the_open_items_are_exactly_the_two_the_other_chapters_name(self):
        self.assertEqual(sorted(i for i, t, s, h in self.ov if s in ("OPEN", "PARTIAL")), ["OV-71", "OV-72", "OV-75", "OV-76", "OV-77", "OV-78", "OV-79"])

    def test_the_ledger_has_as_many_items_as_the_chapter_says(self):
        with open(os.path.join(ROOT, "docs", "56-discrepancy-analysis.md"), encoding="utf-8") as fh:
            n = len(re.findall(r"^\| \d+ \| stage", fh.read(), re.M))
        self.assertIn("`56`: %d items" % n, self.text)

    def test_the_full_suite_evidence_exists_and_is_quoted(self):
        with open(os.path.join(ROOT, "analysis", "evidence-python-suite-summary.txt"), encoding="utf-8") as fh:
            t = fh.read()
        self.assertIn("Ran 864 tests", t)
        self.assertIn("864 tests in 33 minutes", self.text)

    def test_every_procedure_command_names_a_tool_that_exists(self):
        for what, cmd, needs, t, ok in T.PROCEDURES:
            for m in re.finditer(r"tools/([A-Za-z0-9_]+\.(?:py|sh))", cmd):
                self.assertTrue(os.path.exists(os.path.join(ROOT, "tools", m.group(1))), m.group(1))


if __name__ == "__main__":
    unittest.main()
